tool_input.command:
$env:PYTHONIOENCODING='utf-8'
foreach($tn in 'CNEquity-SelectionLake-Update','CNEquity-SelectionLake-Audit'){
  Write-Output "======== $tn ========"
  $t=Get-ScheduledTask -TaskName $tn
  Write-Output "State: $($t.State)"
  $t.Triggers | ForEach-Object { Write-Output ("  Trigger: " + $_.CimClass.CimClassName + " start=" + $_.StartBoundary + " days=" + ($_.DaysOfWeek) + " enabled=" + $_.Enabled) }
  $t.Actions | ForEach-Object { Write-Output ("  Action: " + $_.Execute + " " + $_.Arguments + "  workdir=" + $_.WorkingDirectory) }
  $info=Get-ScheduledTaskInfo -TaskName $tn
  Write-Output ("  LastRun: " + $info.LastRunTime + "  Result: " + $info.LastTaskResult + "  NextRun: " + $info.NextRunTime)
  Write-Output ""
}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== update.log 尾部（上次运行 11-04 22:30 结果）=="
Get-Content 'D:\repository\数据湖\logs\selection_update\update.log' -Tail 25 2>&1 | ForEach-Object {$_}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 计划任务最近运行历史 =="
foreach($tn in 'CNEquity-SelectionLake-Update','CNEquity-SelectionLake-Audit'){
  $info=Get-ScheduledTaskInfo -TaskName $tn
  "$tn : Last=$($info.LastRunTime) Result=$($info.LastTaskResult) Next=$($info.NextRunTime)"
}
Write-Output ""
Write-Output "== update.log 每次运行的起止与结果(按日期) =="
$log='D:\repository\数据湖\logs\selection_update\update.log'
Select-String -Path $log -Pattern 'START|DONE|SUCCESS|status|====|Run finished|exit|ERROR cnequity.orchestrator' | Select-Object -Last 15 | ForEach-Object {"L$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(85,$_.Line.Trim().Length)))"}

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 银行专项抓取相关脚本/配置 =="
Get-ChildItem 'D:\repository\数据湖' -Recurse -Include '*.py','*.json','*.yaml','*.yml' -File -ErrorAction SilentlyContinue | Where-Object {$_.FullName -notmatch '\\logs\\|\\归档|__pycache__'} | ForEach-Object {
  $m=Select-String -Path $_.FullName -Pattern 'bank_risk|HXYJBCZL|RPT_F10_FINANCE|核心一级'
  if($m){ "$(Split-Path $_.FullName -Leaf): $($m.Count)处  ($($_.Directory.Name))" }
} | Select-Object -Unique

$env:PYTHONIOENCODING='utf-8'
Write-Output "== external_lake.py 银行相关 =="
Select-String -Path 'D:\repository\数据湖\分析产出\external_lake.py' -Pattern 'bank|银行|HXYJBCZL|list|BANK|code|RPT_F10|fetch' | Select-Object -First 25 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(90,$_.Line.Trim().Length)))"}
Write-Output "== update_external_lake.py 银行名单/参数 =="
Select-String -Path 'D:\repository\数据湖\分析产出\update_external_lake.py' -Pattern 'bank|银行|BANK|code|--' | Select-Object -First 20 | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(90,$_.Line.Trim().Length)))"}
